// TEMPORARY PROBE — written by the tester to check a re-render edge case not covered by the
// implementer's own suite. Not part of the deliverable; deleted immediately after running.
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmSlideIndicator } from './index';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({ root: {}, dot: {} }),
  };
});

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      {ui}
    </IntlProvider>,
  );

describe('ZimmSlideIndicator — PROBE: re-render with changed props (not exercised by the real suite)', () => {
  test('activeIndex update on a re-render (not a fresh mount) moves the active segment and updates the label', () => {
    const { container, rerender } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
    expect(screen.getByRole('group', { name: 'Image 1 of 5' })).toBeInTheDocument();
    expect(container.querySelectorAll('[data-active="true"]')).toHaveLength(1);

    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSlideIndicator count={5} activeIndex={3} />
      </IntlProvider>,
    );

    // The active node must move, not stay stuck at the value captured on first mount.
    expect(screen.getByRole('group', { name: 'Image 4 of 5' })).toBeInTheDocument();
    const active = container.querySelectorAll('[data-active="true"]');
    expect(active).toHaveLength(1);
  });

  test('count shrinking on a re-render (8 -> 3) while activeIndex stays out of the new range clamps live, not just on mount', () => {
    const { container, rerender } = wrap(<ZimmSlideIndicator count={8} activeIndex={6} />);
    expect(screen.getByRole('group', { name: 'Image 7 of 8' })).toBeInTheDocument();

    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSlideIndicator count={3} activeIndex={6} />
      </IntlProvider>,
    );

    // count-1 = 2 is now the max valid index; the old activeIndex=6 must re-clamp on this
    // render, not carry over a value computed against the previous `count`.
    expect(container.querySelectorAll('[aria-hidden="true"]')).toHaveLength(3);
    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
    expect(container.querySelectorAll('[data-active="true"]')).toHaveLength(1);
  });

  test('count dropping to 1 on a re-render actually unmounts to null, not a stale 1-segment render', () => {
    const { container, rerender } = wrap(<ZimmSlideIndicator count={5} activeIndex={2} />);
    expect(container.querySelectorAll('[aria-hidden="true"]')).toHaveLength(5);

    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSlideIndicator count={1} activeIndex={2} />
      </IntlProvider>,
    );

    expect(container.firstChild).toBeNull();
  });
});
